@Provides
public class HandleStandardException extends JavacAnnotationHandler<StandardException> {
	private static final HandleStandardException SHARED_HANDLER = new HandleStandardException();
	private static final String GETTER_NODE_NOT_SUPPORTED_ERR = "@Getter is only supported on a class, an enum, or a field.";

	private JavacNode activeTypeNode;
	private JavacNode activeSourceNode;
	private AccessLevel activeAccessLevel;
	private JavacTreeMaker activeMaker;
	private JCTree activeExtendsTree;
	private boolean messageParameterRequired;
	private boolean causeParameterRequired;
	private boolean generationAborted;
	private boolean activeTypeIsLocal;
